//! The RP2350 partition table (generated by generate.sh from
//! partition_table.json -- edit the JSON and regenerate, not this file).
//!
//! Linked into the kernel ELF in .partition_table, which the rp2350 linker
//! scripts place at run address 0x1c000000 (the untranslated XIP alias, i.e.
//! flash offset 0 as the CPU can read it) and load address 0x10000000 (flash
//! offset 0): programming the kernel ELF writes the table into sector 0.
//! The layout and why the kernel can stay linked at 0x10000000 are in
//! generate.sh.  124 bytes, picotool `partition create`, with a
//! SHA-256 hash the bootrom checks.

comptime {
    _ = PartitionTable.partition_table;
}

const PartitionTable = struct {
    export const partition_table: [31]u32 linksection(".partition_table") = .{
        0xffffded3, 0x02000e0a, 0xfc008000, 0xfc03e002,
        0xfc021401, 0x00000000, 0x00000000, 0x73617907,
        0x746f6f62, 0xfdffc020, 0xfc021401, 0x00000001,
        0x00000000, 0x73617905, 0x0000736f, 0x00000248,
        0x00010000, 0x01000247, 0x00000013, 0x0000094b,
        0x4fa5a88a, 0x00f2c288, 0x26697f91, 0xbfd115db,
        0xb87673a6, 0x0aa399bb, 0xd0dca6cc, 0xd28ed8a3,
        0x00001bff, 0x00000000, 0xab123579,
    };
};
